// API-01: POST /api/todos priority tests
test('POST /api/todos defaults priority to medium when omitted', async () => {
  const res = await fetch(`${BASE_URL}/api/todos`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ title: 'Priority default test' })
  });
  assert.strictEqual(res.status, 201);
  const data = await res.json();
  assert.strictEqual(data.priority, 'medium');
});

test('POST /api/todos accepts low, medium, and high priority', async () => {
  for (const priority of ['low', 'medium', 'high']) {
    const res = await fetch(`${BASE_URL}/api/todos`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ title: `Priority ${priority} test`, priority })
    });
    assert.strictEqual(res.status, 201);
    const data = await res.json();
    assert.strictEqual(data.priority, priority);
  }
});

test('POST /api/todos rejects invalid priority with 400', async () => {
  for (const priority of ['urgent', 'critical', '', 0, null]) {
    const res = await fetch(`${BASE_URL}/api/todos`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ title: 'Invalid priority test', priority })
    });
    assert.strictEqual(res.status, 400, `Expected 400 for priority: ${JSON.stringify(priority)}`);
  }
});

// API-02: PUT /api/todos/:id priority tests
test('PUT /api/todos/:id can change priority to a valid value', async () => {
  const createRes = await fetch(`${BASE_URL}/api/todos`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ title: 'Priority update test', priority: 'low' })
  });
  const created = await createRes.json();

  const updateRes = await fetch(`${BASE_URL}/api/todos/${created.id}`, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ priority: 'high' })
  });
  assert.strictEqual(updateRes.status, 200);
  const updated = await updateRes.json();
  assert.strictEqual(updated.priority, 'high');
});

test('PUT /api/todos/:id rejects invalid priority with 400 and changes nothing', async () => {
  const createRes = await fetch(`${BASE_URL}/api/todos`, {
